body:
{
  "pains": [
    {
      "id": "pain:no-soc2-no-deal",
      "statement": "A customer wants to sign, then procurement sends a security questionnaire or asks for our SOC 2, and as a tiny team we either fake our way through it, spend $20k on auditors, or lose the deal.",
      "element": "b2b:functional:improved_top_line",
      "shape": {
        "surface": "A prospect who liked the product sends a questionnaire or asks about certification, and the honest answer to many of the questions is no.",
        "operational": "The founder answers it alone, attests to the boxes they cannot tick, prices out a $20k+ audit, or tells enterprise prospects to go away.",
        "personal": "The founder decides between a costly audit nobody planned for and walking away from revenue; one says he would rather lose the deal."
      },
      "workflow": "The week after a good demo, when the prospect's procurement team emails an Excel security questionnaire or a request for a SOC 2 Type 2 report, and the solo founder or CTO opens it alone.",
      "type": "felt",
      "confidence": "high",
      "priority": 1,
      "felt_evidence": {
        "kind": "complaining",
        "what": "A founder posted on Hacker News in May 2026 that customers keep asking about certification for his app and asked how to get SOC 2 Type 2 without spending $20k+ on auditors.",
        "cites": ["src:3"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "A first enterprise prospect's procurement sends its own security questionnaire as a spreadsheet.",
          "cites": ["src:16"]
        },
        {
          "event": "Enterprise customers bring their own questionnaires that a small business cannot pass as written.",
          "cites": ["src:4"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "My customers bombards me with question about certification of my app Perfect Wiki,",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "My company is tiny (just me) and at one point a client sent over a questionnaire that I needed to fill out.",
              "cites": ["src:5"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "decided I’d rather lose the deal than try to do those things.",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "I learned that my business is unable to pass pretty much ANY certification or corporate IT security audit.",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "The deal itself, or $20k+ and months of founder time on an audit they did not budget for.",
          "fears": "That a single enterprise questionnaire decides whether the company can sell upmarket at all.",
          "dream_outcome": "Answer the questionnaire honestly and still close the contract."
        }
      },
      "relief": {
        "line": "Contract signed. The questionnaire got an honest answer and the deal still closed.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "As a 1-man show I went through the same thing, still got the contract",
            "cites": ["src:6"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Upmarket by default. Enterprise procurement becomes a routine step instead of a deal risk.",
        "says": [],
        "gap": "Read the Ask HN SOC 2 thread (May 2026) and the Delve thread (March 2026); founders describe getting through one deal, none describes the standing change a year later. G2 and Capterra four and five star reviews were blocked (403)."
      },
      "segments": ["seg:startup"],
      "feature_ref": "feat:automated",
      "feature_note": "Automated compliance gets the SOC 2 report that procurement asks for; the questionnaire half of this pain also points at feat:questionnaire.",
      "cites": ["src:3", "src:5"]
    },
    {
      "id": "pain:screenshots-for-the-auditor",
      "statement": "Half of SOC 2 is me taking screenshots of cloud consoles and Splunk searches for the auditor, by hand, every audit.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "The auditor's evidence request list, and a folder of screenshots of consoles, command output and settings pages.",
        "operational": "Engineers pull screenshots and exports from every system by hand, or gather artifacts across Jira, ServiceNow, email and Teams chat, and redo it when the auditor asks for more.",
        "personal": "Engineers spend audit season as the auditor's screenshot clerk on work they call performative and, in one engineer's word, vomit."
      },
      "workflow": "During the SOC 2 audit window: run the Splunk search, screenshot it, capture AWS/cloud console pages and command output, then chase artifacts in Jira, ServiceNow, email and Teams and upload them to the auditor.",
      "type": "felt",
      "confidence": "high",
      "priority": 2,
      "felt_evidence": {
        "kind": "paying",
        "what": "A small IT team reviewing Vanta in October 2026 says they pay for it because evidence collection used to mean pulling screenshots and exports by hand.",
        "cites": ["src:1"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "The audit window opens and the auditor asks for more evidence on demand.",
          "cites": ["src:14"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "I sent screenshots to auditors constantly",
              "cites": ["src:11"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I ran this splunk search, here's a screenshot",
              "cites": ["src:11"]
            },
            {
              "situation": "venting",
              "verbatim": "But a lot of the \"evidence\" I sent was just screenshots.",
              "cites": ["src:12"]
            },
            {
              "situation": "venting",
              "verbatim": "it's a huge pain grabbing screenshots for what feels like a very performative process",
              "cites": ["src:13"]
            },
            {
              "situation": "venting",
              "verbatim": "Oftentimes evidence is screenshots of the running environment (vomit) or audit logs.",
              "cites": ["src:14"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I've been collecting compliance artifacts via JIRA, ServiceNow, email and Teams Chat.",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "Before, collecting evidence meant pulling screenshots and exports from lots of systems by hand.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Days of engineering time each audit spent capturing and uploading screenshots instead of shipping.",
          "fears": "No source states the fear directly; the quotes stop at the cost and the disgust.",
          "dream_outcome": "Evidence already sitting in one place when the auditor asks."
        }
      },
      "relief": {
        "line": "Audit prep is a folder. The evidence is in one place, ready to hand to the auditor.",
        "says": [
          {
            "role": "end_user",
            "verbatim": "evidence was organised in one place and easy to hand to the auditor.",
            "cites": ["src:1"]
          },
          {
            "role": "end_user",
            "verbatim": "Vanta keeps us on top of compliance without it turning into a full-time job.",
            "cites": ["src:1"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Audit season disappears. The team stops planning quarters around the auditor.",
        "says": [],
        "gap": "Read AWS Marketplace reviews for Vanta and Drata and the HN screenshot threads; reviewers describe relief at audit time, none describes the year after."
      },
      "segments": ["seg:scaling", "seg:startup"],
      "feature_ref": "feat:automated",
      "cites": ["src:11", "src:1"]
    },
    {
      "id": "pain:questionnaire-spreadsheets",
      "statement": "Even with SOC 2 and ISO 27001 in hand, every prospect still sends their own security spreadsheet, the requests never stop, and I doubt anyone reads the answers.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "A steady stream of security assessment spreadsheets from potential customers, each worded differently.",
        "operational": "The CTO or security lead fills each one by hand, even after the certifications that were meant to replace them.",
        "personal": "Hours go into answers the person filling them in believes the requester never reads."
      },
      "workflow": "Mid-deal, when a prospect's procurement emails a big Excel security questionnaire and the CTO or security lead answers it row by row, alongside the SOC 2 Type 2 and ISO 27001 reports they already sent.",
      "type": "felt",
      "confidence": "medium",
      "priority": 3,
      "felt_evidence": {
        "kind": "paying",
        "what": "An education-sector Vanta customer reviewing it in October 2026 credits the knowledge base and trust centre with saving time on questionnaires.",
        "cites": ["src:1"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "A prospect's procurement sends a big Excel questionnaire during the sale.",
          "cites": ["src:16"]
        }
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Yeah, I get this even with SOC2 Type 2 & ISO 27001 ... the requests never stop.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "And yet, you still have to fill them in, because the people who ask you for them don't actually care to read them",
              "cites": ["src:15"]
            }
          ],
          "costs_them": "Recurring hours on each new prospect's spreadsheet, on top of the audits.",
          "fears": "That the certifications bought to end the questionnaires never do.",
          "dream_outcome": "Send one answer set or one page and have the prospect accept it."
        },
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "we had so many security assessments spreadsheets sent by potential customers,",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "The CTO's own time at a six-person company, pulled off the product.",
          "fears": "No source shows the economic buyer's fear; the quote stops at the volume.",
          "dream_outcome": "Questionnaires handled without the CTO in the loop."
        }
      },
      "relief": {
        "line": "Questionnaires answer themselves. The knowledge base and trust centre handle most of it.",
        "says": [
          {
            "role": "end_user",
            "verbatim": "the knowledge base and trust centre - questionnaires are saving a great deal of time and effort.",
            "cites": ["src:1"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Security becomes a sales asset. Prospects self-serve the answers and deals move faster.",
        "says": [],
        "gap": "Looked in AWS Marketplace Vanta and Drata reviews and HN threads; one review describes time saved, none describes security turning into a selling point."
      },
      "segments": ["seg:startup", "seg:scaling"],
      "feature_ref": "feat:questionnaire",
      "feature_note": "feat:trust (Trust Center) is the other half of the relief the reviewer names.",
      "cites": ["src:3", "src:15"]
    },
    {
      "id": "pain:where-do-we-even-start",
      "statement": "We need SOC 2, but nobody here has done it, we don't know where to start or what we already have, and we don't want to spend $20k on auditors finding out.",
      "element": "b2b:ease_of_doing_business:expertise",
      "shape": {
        "surface": "A requirement to get compliant with no map of which controls exist and which are missing.",
        "operational": "Someone cobbles together a SOC 2 program from forum advice and templates.",
        "personal": null,
        "personal_note": "No source shows what this costs the person; the founder posts and the review stop at not knowing where to start. Asked in q:pains-personal-rung."
      },
      "workflow": "The first week after deciding to get SOC 2: the founder or first IT hire searches Ask HN and vendor sites for how to start, before any auditor or tool is chosen.",
      "type": "felt",
      "confidence": "medium",
      "priority": 4,
      "felt_evidence": {
        "kind": "paying",
        "what": "A solo founder who just completed SOC 2 a second time recommends paying for Vanta because it holds your hand through half the process.",
        "cites": ["src:3"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "Customers start asking about the app's certification.",
          "cites": ["src:3"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "We wanted to get compliant, but we didn’t know where to start or what we already had versus what was missing.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_looking",
              "verbatim": "Is it possible? Do you know success cases w/o spending 20+k $ on auditors?",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "As someone who had to cobble together a soc2 program - this is mostly true.",
              "cites": ["src:3"]
            }
          ],
          "costs_them": "Weeks of guessing at controls, and the risk of paying an auditor to find the gaps.",
          "fears": "Spending $20k+ on auditors without knowing whether they will pass.",
          "dream_outcome": "A clear list of what they have and what is missing, and someone to walk them through the rest."
        }
      },
      "relief": {
        "line": "Somebody holds your hand. The gaps are listed and the next step is obvious.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "Personally I'd recommend Vanta which will hold your hand through at least half the process.",
            "cites": ["src:3"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Compliance as a known quantity. The founder can promise a SOC 2 date on a sales call.",
        "says": [],
        "gap": "Read the Ask HN SOC 2 thread and AWS Marketplace Vanta reviews; buyers describe hand-holding, none describes the year after."
      },
      "segments": ["seg:startup"],
      "feature_ref": "feat:automated",
      "feature_note": "The reviewer credits gap detection and pre-written tests, which sit inside automated compliance.",
      "cites": ["src:1", "src:3"]
    },
    {
      "id": "pain:templated-soc2-reports",
      "statement": "When I vet a vendor, half the SOC 2 reports I get are the same pre-populated template, so the report tells me nothing about whether they actually have the controls.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "Vendor SOC 2 reports and policies that read identically across unrelated companies.",
        "operational": "The reviewer independently checks vendors' reports against each other instead of trusting the auditor's opinion.",
        "personal": null,
        "personal_note": "No source shows the personal cost to the reviewer; the comments stop at the report being meaningless. Asked in q:pains-personal-rung."
      },
      "workflow": "In vendor intake: the security reviewer opens the SOC 2 report a new software vendor sent and compares its policies and controls with other vendors' reports before approving the purchase.",
      "type": "felt",
      "confidence": "medium",
      "priority": 5,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Vendor reviewers complained publicly in March 2026, on the Hacker News thread about fake compliance reports, that vendors send the same templated SOC 2.",
        "cites": ["src:8"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "Public news of fake SOC 2 reports (the Delve thread, March 2026) sends reviewers back to check vendors' reports.",
          "cites": ["src:8"]
        }
      ],
      "who_feels": ["technical_evaluator"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I have independently verified for our vendors that they have the same templated SOC2",
              "cites": ["src:8"]
            },
            {
              "situation": "venting",
              "verbatim": "If the SOC2 report is just a pre-populated template, it is meaningless.",
              "cites": ["src:8"]
            },
            {
              "situation": "venting",
              "verbatim": "Taking cookie cutter policies/controls jamming it into your org without any awareness whatsoever.",
              "cites": ["src:9"]
            },
            {
              "situation": "venting",
              "verbatim": "I have seen companies just rubber stamp pre-created documents",
              "cites": ["src:24"]
            }
          ],
          "costs_them": "Extra verification work on every vendor, since the report no longer settles the question.",
          "fears": "Approving a vendor whose clean report hides missing controls.",
          "dream_outcome": "A vendor report that reflects that company's real controls."
        }
      },
      "relief": {
        "line": "Reports you can trust. The SOC 2 a vendor sends matches what they run.",
        "says": [],
        "gap": "Searched the Delve HN thread and AWS reviews; reviewers describe the problem, none describes a fix."
      },
      "euphoria": {
        "line": "Vendor review gets fast. The reviewer approves good vendors in a day.",
        "says": [],
        "gap": "No after-state found in any source read."
      },
      "segments": ["seg:scaling"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company proves a vendor's report is real; feat:tpr reviews vendors but no source shows it detecting templated reports. The same thread names Vanta's own default policies as long and complex (src:10), so the category is partly blamed for this pain.",
      "cites": ["src:8", "src:9"]
    },
    {
      "id": "pain:integrations-back-to-manual",
      "statement": "We bought the compliance tool to stop doing it by hand, but the integrations are limited, syncs lag and the agent misbehaves, so we're back to re-checking manually.",
      "element": "b2b:ease_of_doing_business:integration",
      "shape": {
        "surface": "A test still failing after the fix, a stale sync, a device monitoring agent acting up.",
        "operational": "The team re-checks manually or waits for the sync before confirming a fix, and covers gaps where the integration has no test.",
        "personal": null,
        "personal_note": "No source shows the personal cost; reviewers stop at the extra manual work. Asked in q:pains-personal-rung."
      },
      "workflow": "After fixing a failing control in Google Workspace or on a laptop, in the compliance platform's dashboard, waiting for the integration sync or device monitoring agent to confirm the fix.",
      "type": "felt",
      "confidence": "medium",
      "priority": 6,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Vanta and Drata customers name limited integrations, slow syncs and a misbehaving agent in reviews dated September and October 2026.",
        "cites": ["src:1", "src:2"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "Fixing a failing control and needing to confirm it before an audit.",
          "cites": ["src:1"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Some integrations are more limited than we'd like, and syncs don't always refresh quickly.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "so we sometimes re-check manually or wait before we can confirm a fix.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "The plugin they have, sometime start misbehaving, specially the device monitoring agent they have.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "Integration, Monitoring, Connections, and lack of complete set of tests.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Manual re-checks and waiting time the tool was bought to remove.",
          "fears": "No source states the fear; the quotes stop at the extra work.",
          "dream_outcome": "Fix the control and see it pass right away."
        }
      },
      "relief": {
        "line": "Fix it and it's green. The test passes the moment the fix lands.",
        "says": [],
        "gap": "Read AWS Marketplace reviews for Vanta and Drata; integration complaints have no matching after-state quote."
      },
      "euphoria": {
        "line": "Hands-off compliance. The team trusts the dashboard without checking it.",
        "says": [],
        "gap": "No source read describes it."
      },
      "segments": ["seg:scaling", "seg:regulated"],
      "feature_ref": "feat:automated",
      "feature_note": "This is a pain inside the category, Vanta included: its own reviewers name it. Positioning should read it as a switching risk as much as a pain to sell against.",
      "cites": ["src:1", "src:2"]
    },
    {
      "id": "pain:audit-every-four-months",
      "statement": "We're PCI, HITRUST and SOC 2 at once, so there's an audit almost every four months, and every framework wants the same controls proven again.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "Overlapping audit calendars across PCI, URAC, HITRUST, SOC 2 and ISO 27001.",
        "operational": "The same team runs back-to-back audits, re-proving overlapping controls for each framework.",
        "personal": "Audit season never ends; the person calls it infuriating."
      },
      "workflow": "In a healthcare or payments company, the compliance or security engineer moving from the PCI audit to the HITRUST audit to the SOC 2 audit across the year.",
      "type": "felt",
      "confidence": "low",
      "priority": 7,
      "felt_evidence": {
        "kind": "complaining",
        "what": "A healthcare employee complained in April 2025 about PCI, URAC and HITRUST audits arriving almost every four months.",
        "cites": ["src:17"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "The next audit in a cycle of one every four months.",
          "cites": ["src:17"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Honestly its infuriating that the company I work for gets PCI, URAC and HiTrust audits",
              "cites": ["src:17"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "we have an audit almost every 4 months",
              "cites": ["src:17"]
            },
            {
              "situation": "venting",
              "verbatim": "And in addition the costs are stupid high for startups that are just",
              "cites": ["src:18"]
            }
          ],
          "costs_them": "A year spent in audit prep and high audit fees across frameworks.",
          "fears": "No source states the fear; the quotes stop at the frequency and cost.",
          "dream_outcome": "Prove a control once and have it count for every framework."
        }
      },
      "relief": {
        "line": "One set of controls. Multiple frameworks run from a single place.",
        "says": [
          {
            "role": "end_user",
            "verbatim": "Vanta minimizes fragmentation and administrative duties in managing multi-framework compliance.",
            "cites": ["src:1"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Audits become routine. A new framework is a week's work, not a new program.",
        "says": [],
        "gap": "Regulated segment got a three-source probe only; no after-state found."
      },
      "segments": ["seg:regulated"],
      "feature_ref": "feat:grc",
      "feature_note": "Confidence low: two HN comments from different contexts (healthcare, PCI startups), and the regulated segment was probed, not deep-swept.",
      "cites": ["src:17", "src:18"]
    },
    {
      "id": "pain:noisy-alerts",
      "statement": "The compliance tool's notifications are so noisy, with so little context, that I can't tell which alert actually needs me.",
      "element": "b2b:ease_of_doing_business:decreased_hassles",
      "shape": {
        "surface": "A flood of notifications and alerts from continuous monitoring.",
        "operational": "The team triages alerts by hand to find the next action.",
        "personal": null,
        "personal_note": "No source shows the personal cost; one reviewer says it makes the tool hard to win support for internally, which is the closest. Asked in q:pains-personal-rung."
      },
      "workflow": "Daily, in the compliance platform's notification feed and email alerts, deciding which failing test needs action.",
      "type": "felt",
      "confidence": "medium",
      "priority": 8,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Vanta and Drata customers each called the alerts noisy in reviews dated August to October 2026.",
        "cites": ["src:1", "src:2"]
      },
      "revealed_by": null,
      "triggers": [],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Notifications - one of the noisiest systems I have ever used.",
              "cites": ["src:1"]
            },
            {
              "situation": "venting",
              "verbatim": "Alerts can also feel noisy or lack enough context to make the next action immediately clear.",
              "cites": ["src:2"]
            },
            {
              "situation": "to_their_boss",
              "verbatim": "Difficult to gain support for it as a system when it behaves as such.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Triage time, and internal support for the tool.",
          "fears": "That colleagues tune out the tool and real failures get missed.",
          "dream_outcome": "Only the alerts that need action, each with the next step."
        }
      },
      "relief": {
        "line": "Quiet inbox. Each alert says what to do next.",
        "says": [],
        "gap": "Read AWS Marketplace reviews for Vanta and Drata; complaints only."
      },
      "euphoria": {
        "line": "The tool is trusted company-wide. People act on alerts the day they land.",
        "says": [],
        "gap": "No source read describes it."
      },
      "segments": ["seg:scaling"],
